#nullable enable // autogenerated

using PVZEngine.Tools.Unity;
using UnityEngine;
using UnityEngine.UI;

namespace MVZ2Logic.UI
{
    [RequireComponent(typeof(SpriteRenderer))]
    public class SpriteRendererResolver : MonoBehaviour, ISpriteResolver
    {
        private void OnEnable()
        {
            if (!spriteChanged)
            {
                spriteChanged = true;
                BaseSprite = Renderer.sprite;
            }
            SetSprite(BaseSprite);
        }
        public virtual void SetSprite(Sprite? sprite)
        {
            var final = sprite;
            if (Global.Resources != null && final != null)
            {
                final = Global.Resources.GetFinalSprite(final);
            }
            spriteChanged = true;
            BaseSprite = sprite;
            Renderer.sprite = final;
        }
        public virtual Sprite? GetSprite()
        {
            return Renderer.sprite;
        }
        public virtual void SetEnabled(bool enabled)
        {
            Renderer.enabled = enabled;
        }
        public virtual void SetSpriteAndEnabled(Sprite? sprite)
        {
            SetSprite(sprite);
            Renderer.enabled = sprite;
        }
        public void GetPropertyBlock(MaterialPropertyBlock propertyBlock)
        {
            Renderer.GetPropertyBlock(propertyBlock);
        }
        public void SetPropertyBlock(MaterialPropertyBlock propertyBlock)
        {
            Renderer.SetPropertyBlock(propertyBlock);
        }
        public Sprite? BaseSprite { get; private set; }
        public SpriteRenderer Renderer
        {
            get
            {
                if (!_renderer.Exists())
                {
                    _renderer = GetComponent<SpriteRenderer>();
                }
                return _renderer;
            }
        }
        public virtual Sprite? spriteMark { get => Renderer.sprite; set => Renderer.sprite = value; }
        public virtual Color color { get => Renderer.color; set => Renderer.color = value; }
        public virtual int sortingOrder { get => Renderer.sortingOrder; set => Renderer.sortingOrder = value; }
        public virtual int sortingLayerID { get => Renderer.sortingLayerID; set => Renderer.sortingLayerID = value; }
        public virtual Vector2 size { get => Renderer.size; set => Renderer.size = value; }
        private SpriteRenderer? _renderer;
        private bool spriteChanged;
    }
}
